ob(label, currentMatch, searchString) {
        if (label === $Nfb) {
            return searchString === ''
                ? nls.localize(1037, null, label)
                : nls.localize(1038, null, label, searchString);
        }
        if (currentMatch) {
            const ariaLabel = nls.localize(1039, null, label, searchString, currentMatch.startLineNumber + ':' + currentMatch.startColumn);
            const model = this.c.getModel();
            if (model && (currentMatch.startLineNumber <= model.getLineCount()) && (currentMatch.startLineNumber >= 1)) {
                const lineContent = model.getLineContent(currentMatch.startLineNumber);
                return `${lineContent}, ${ariaLabel}`;
            }
            return ariaLabel;
        }
        return nls.localize(1040, null, label, searchString);
    }
